import{_ as l,o as e,c as i,ak as r}from"./chunks/framework.DvrM7GBU.js";const p=JSON.parse('{"title":"创游世界术语表","description":"","frontmatter":{},"headers":[],"relativePath":"元信息/创游世界术语表.md","filePath":"元信息/创游世界术语表.md","lastUpdated":1777893104000}'),h={name:"元信息/创游世界术语表.md"};function d(n,a,o,s,c,_){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="创游世界术语表" tabindex="-1">创游世界术语表 <a class="header-anchor" href="#创游世界术语表" aria-label="Permalink to “创游世界术语表”">​</a></h1><ul><li>分类：维护规范</li><li>子系统：知识库工程 / 术语标准 / 检索结构</li><li>关键词标签：术语表, 名词解释, 素材, 物体, 组件, 自定义组件, 指令, 广播, UI, 地图属性, 系统属性, 云变量</li><li>来源类型：官方教程 / 脚本界面截图 / 引擎更新 / 现有专题交叉整理</li><li>证据等级：多来源交叉归纳</li><li>完整度状态：持续扩展中</li><li>来源文件：<code>docs/教程资料/官方教程知识索引.md</code>; <code>docs/脚本系统/脚本界面与积木知识索引.md</code>; <code>docs/引擎更新/引擎更新知识索引.md</code></li><li>最后更新：2026-04-20</li><li>适合查询：术语是什么意思、概念之间有什么区别、文档里某个名词该怎么理解</li></ul><h2 id="_1-文档目的" tabindex="-1">1. 文档目的 <a class="header-anchor" href="#_1-文档目的" aria-label="Permalink to “1. 文档目的”">​</a></h2><p>本术语表用于统一 <code>创游世界资料汇总</code> 中常见名词的解释口径，减少不同文档对同一概念使用不同说法造成的混乱。</p><p>它不追求一次性解释所有概念，而是先把高频、最容易混淆、最影响后续项目设计和 AI 检索的术语统一下来。</p><hr><h2 id="_2-基础对象层" tabindex="-1">2. 基础对象层 <a class="header-anchor" href="#_2-基础对象层" aria-label="Permalink to “2. 基础对象层”">​</a></h2><h3 id="_2-1-素材" tabindex="-1">2.1 素材 <a class="header-anchor" href="#_2-1-素材" aria-label="Permalink to “2.1 素材”">​</a></h3><p>通常指可被创建、摆放、复用、编辑的资源模板。素材更接近“模板”或“资源定义”，不是地图中的某个实时实例本身。</p><p>常见误区：</p><ul><li>把素材和地图上的物体当成完全一样的东西</li><li>修改素材后，误以为场景中的所有旧物体会自动同步变化</li></ul><p>关联阅读：</p><ul><li><code>docs/教程资料/专题研究/素材实例化与地图物体关系解析.md</code></li><li><code>docs/教程资料/专题研究/创游世界对象_素材_组件_脚本关系总图.md</code></li></ul><h3 id="_2-2-物体" tabindex="-1">2.2 物体 <a class="header-anchor" href="#_2-2-物体" aria-label="Permalink to “2.2 物体”">​</a></h3><p>通常指地图里实际存在、可运行、可交互、可被脚本控制的实例对象。一个物体往往来自某个素材被放入地图后的实例化结果。</p><p>常见误区：</p><ul><li>直接在实例上改值后，又回头期待原素材同步变化</li><li>不区分“模板修改”和“实例修改”</li></ul><h3 id="_2-3-实例化" tabindex="-1">2.3 实例化 <a class="header-anchor" href="#_2-3-实例化" aria-label="Permalink to “2.3 实例化”">​</a></h3><p>指把素材变成地图里的具体对象。实例化后，对象会带着创建时的属性快照进入地图运行环境。</p><p>关键理解：</p><ul><li>素材像模具</li><li>实例像已经做出来的成品</li></ul><hr><h2 id="_3-组件与脚本层" tabindex="-1">3. 组件与脚本层 <a class="header-anchor" href="#_3-组件与脚本层" aria-label="Permalink to “3. 组件与脚本层”">​</a></h2><h3 id="_3-1-组件" tabindex="-1">3.1 组件 <a class="header-anchor" href="#_3-1-组件" aria-label="Permalink to “3.1 组件”">​</a></h3><p>组件是给对象附加能力的功能单元。不同组件负责不同能力，例如显示、交互、战斗、装置、粒子、生命等。</p><p>关键理解：</p><ul><li>对象本身只是载体</li><li>组件决定对象“会什么”</li></ul><h3 id="_3-2-自定义组件" tabindex="-1">3.2 自定义组件 <a class="header-anchor" href="#_3-2-自定义组件" aria-label="Permalink to “3.2 自定义组件”">​</a></h3><p>由开发者自己定义输入属性、可调用指令、触发时机的组件封装形式。适合沉淀复用逻辑，而不是把同一套脚本在多个对象上反复手抄。</p><p>适合场景：</p><ul><li>可复用交互逻辑</li><li>通用血条刷新逻辑</li><li>标准化按钮行为</li><li>可配置型机关行为</li></ul><h3 id="_3-3-指令" tabindex="-1">3.3 指令 <a class="header-anchor" href="#_3-3-指令" aria-label="Permalink to “3.3 指令”">​</a></h3><p>指可以被执行的脚本动作单元，常见为“做某件事”的操作块。它更强调执行行为，不是纯数据。</p><h3 id="_3-4-触发时机" tabindex="-1">3.4 触发时机 <a class="header-anchor" href="#_3-4-触发时机" aria-label="Permalink to “3.4 触发时机”">​</a></h3><p>指脚本在什么事件或条件下被启动。比如点击时、生成时、命中时、击杀时等。它决定逻辑何时开始运行。</p><p>常见误区：</p><ul><li>不区分“定义了逻辑”和“何时触发逻辑”</li><li>所有逻辑都塞进单一触发入口导致后期难维护</li></ul><hr><h2 id="_4-数据与作用域层" tabindex="-1">4. 数据与作用域层 <a class="header-anchor" href="#_4-数据与作用域层" aria-label="Permalink to “4. 数据与作用域层”">​</a></h2><h3 id="_4-1-局部变量" tabindex="-1">4.1 局部变量 <a class="header-anchor" href="#_4-1-局部变量" aria-label="Permalink to “4.1 局部变量”">​</a></h3><p>只在当前脚本过程、局部逻辑片段或短时计算里使用的数据。适合临时中间值，不适合长期状态保存。</p><h3 id="_4-2-自身属性" tabindex="-1">4.2 自身属性 <a class="header-anchor" href="#_4-2-自身属性" aria-label="Permalink to “4.2 自身属性”">​</a></h3><p>挂在当前对象自己身上的状态值。适合表示对象私有状态，例如当前血量、是否已激活、冷却剩余等。</p><h3 id="_4-3-地图属性" tabindex="-1">4.3 地图属性 <a class="header-anchor" href="#_4-3-地图属性" aria-label="Permalink to “4.3 地图属性”">​</a></h3><p>属于当前地图层的共享状态。适合被同一地图多个对象共同访问的数据，例如地图进度、当前波次、公共资源池等。</p><h3 id="_4-4-系统属性" tabindex="-1">4.4 系统属性 <a class="header-anchor" href="#_4-4-系统属性" aria-label="Permalink to “4.4 系统属性”">​</a></h3><p>比地图层更高一层的全局状态。适合跨地图、全局流程、胜负控制、切图、全局计时等。</p><h3 id="_4-5-云变量" tabindex="-1">4.5 云变量 <a class="header-anchor" href="#_4-5-云变量" aria-label="Permalink to “4.5 云变量”">​</a></h3><p>与持久化、同步、跨次访问等需求相关的变量能力。它更接近“外部保存层”，而不是普通临时运行变量。</p><p>注意：</p><ul><li>云变量不适合滥用来替代所有本地运行状态</li><li>需要先明确哪些值真有持久化需求</li></ul><h3 id="_4-6-结构体" tabindex="-1">4.6 结构体 <a class="header-anchor" href="#_4-6-结构体" aria-label="Permalink to “4.6 结构体”">​</a></h3><p>用于组织多字段数据的一种结构化表示方式，适合把一组相关属性放在一起管理。</p><p>适合场景：</p><ul><li>背包物品记录</li><li>任务条目</li><li>技能配置</li><li>玩家统计信息</li></ul><hr><h2 id="_5-ui-与交互层" tabindex="-1">5. UI 与交互层 <a class="header-anchor" href="#_5-ui-与交互层" aria-label="Permalink to “5. UI 与交互层”">​</a></h2><h3 id="_5-1-ui" tabindex="-1">5.1 UI <a class="header-anchor" href="#_5-1-ui" aria-label="Permalink to “5.1 UI”">​</a></h3><p>用户界面。用于显示信息、接收操作、反馈状态。UI 更偏显示与输入，不应该承载过多底层真值逻辑。</p><h3 id="_5-2-地图ui" tabindex="-1">5.2 地图UI <a class="header-anchor" href="#_5-2-地图ui" aria-label="Permalink to “5.2 地图UI”">​</a></h3><p>与当前地图场景关联的界面层，常用于地图内信息展示和交互。</p><h3 id="_5-3-操作ui" tabindex="-1">5.3 操作UI <a class="header-anchor" href="#_5-3-操作ui" aria-label="Permalink to “5.3 操作UI”">​</a></h3><p>偏向按钮、操作区、快捷操作入口等功能性界面。</p><h3 id="_5-4-物体ui" tabindex="-1">5.4 物体UI <a class="header-anchor" href="#_5-4-物体ui" aria-label="Permalink to “5.4 物体UI”">​</a></h3><p>与特定物体绑定或由物体触发的界面展示方式。</p><h3 id="_5-5-当前ui" tabindex="-1">5.5 当前UI <a class="header-anchor" href="#_5-5-当前ui" aria-label="Permalink to “5.5 当前UI”">​</a></h3><p>指当前正在运行、被访问、被脚本引用的 UI 上下文。联机与本地逻辑演进后，这个概念尤其重要。</p><h3 id="_5-6-上传并等待" tabindex="-1">5.6 上传并等待 <a class="header-anchor" href="#_5-6-上传并等待" aria-label="Permalink to “5.6 上传并等待”">​</a></h3><p>在联机或公共状态同步场景中，用于确保数据先上传或同步完成，再继续后续依赖逻辑的一种处理思路。</p><p>关键理解：</p><ul><li>它是在处理“时序问题”</li><li>不是普通等待几秒就能稳定替代的东西</li></ul><hr><h2 id="_6-通信与架构层" tabindex="-1">6. 通信与架构层 <a class="header-anchor" href="#_6-通信与架构层" aria-label="Permalink to “6. 通信与架构层”">​</a></h2><h3 id="_6-1-广播" tabindex="-1">6.1 广播 <a class="header-anchor" href="#_6-1-广播" aria-label="Permalink to “6.1 广播”">​</a></h3><p>一种事件化消息传递机制，用于降低模块之间的直接耦合。常用于 UI、地图对象、系统层之间传递动作意图或状态变化通知。</p><p>适合场景：</p><ul><li>UI 按钮通知地图执行某动作</li><li>战斗事件驱动音效/UI反馈</li><li>任务推进时同步多个系统</li></ul><h3 id="_6-2-地图广播" tabindex="-1">6.2 地图广播 <a class="header-anchor" href="#_6-2-地图广播" aria-label="Permalink to “6.2 地图广播”">​</a></h3><p>在地图层或对象层范围内传播的广播方式，常作为 UI 与地图系统之间的桥梁。</p><h3 id="_6-3-解耦" tabindex="-1">6.3 解耦 <a class="header-anchor" href="#_6-3-解耦" aria-label="Permalink to “6.3 解耦”">​</a></h3><p>指让不同模块不要互相写死依赖。广播、统一数据源、组件封装，都是常见的解耦手段。</p><hr><h2 id="_7-工程与研究层" tabindex="-1">7. 工程与研究层 <a class="header-anchor" href="#_7-工程与研究层" aria-label="Permalink to “7. 工程与研究层”">​</a></h2><h3 id="_7-1-ocr" tabindex="-1">7.1 OCR <a class="header-anchor" href="#_7-1-ocr" aria-label="Permalink to “7.1 OCR”">​</a></h3><p>把截图内容转为可检索文本的过程。这里不仅是“识别文字”，还包括人工纠错、主题归档、编号追踪与证据回填。</p><h3 id="_7-2-映射表" tabindex="-1">7.2 映射表 <a class="header-anchor" href="#_7-2-映射表" aria-label="Permalink to “7.2 映射表”">​</a></h3><p>把图片编号、主题、状态、对应文档、对应专题串起来的追溯表。它是 OCR 工程的重要索引层。</p><h3 id="_7-3-证据等级" tabindex="-1">7.3 证据等级 <a class="header-anchor" href="#_7-3-证据等级" aria-label="Permalink to “7.3 证据等级”">​</a></h3><p>用于区分结论来自官方文本、截图直接证据、交叉归纳、社区推测还是待验证线索。</p><h3 id="_7-4-完整度状态" tabindex="-1">7.4 完整度状态 <a class="header-anchor" href="#_7-4-完整度状态" aria-label="Permalink to “7.4 完整度状态”">​</a></h3><p>用于说明文档处于草稿、已整理、深度整理、持续扩展中还是近完整等阶段。</p><hr><h2 id="_8-当前最容易混淆的几组概念" tabindex="-1">8. 当前最容易混淆的几组概念 <a class="header-anchor" href="#_8-当前最容易混淆的几组概念" aria-label="Permalink to “8. 当前最容易混淆的几组概念”">​</a></h2><h3 id="_8-1-素材-vs-物体" tabindex="-1">8.1 素材 vs 物体 <a class="header-anchor" href="#_8-1-素材-vs-物体" aria-label="Permalink to “8.1 素材 vs 物体”">​</a></h3><ul><li>素材：模板/资源定义</li><li>物体：地图里的运行实例</li></ul><h3 id="_8-2-显示值-vs-真值" tabindex="-1">8.2 显示值 vs 真值 <a class="header-anchor" href="#_8-2-显示值-vs-真值" aria-label="Permalink to “8.2 显示值 vs 真值”">​</a></h3><ul><li>显示值：UI 上看到的数</li><li>真值：真正驱动逻辑判断的数据</li></ul><h3 id="_8-3-地图属性-vs-系统属性" tabindex="-1">8.3 地图属性 vs 系统属性 <a class="header-anchor" href="#_8-3-地图属性-vs-系统属性" aria-label="Permalink to “8.3 地图属性 vs 系统属性”">​</a></h3><ul><li>地图属性：当前地图范围共享状态</li><li>系统属性：更高层、跨地图或全局流程状态</li></ul><h3 id="_8-4-组件-vs-自定义组件" tabindex="-1">8.4 组件 vs 自定义组件 <a class="header-anchor" href="#_8-4-组件-vs-自定义组件" aria-label="Permalink to “8.4 组件 vs 自定义组件”">​</a></h3><ul><li>组件：内置或现成能力单元</li><li>自定义组件：开发者自己封装的能力单元</li></ul><h3 id="_8-5-广播-vs-直接改值" tabindex="-1">8.5 广播 vs 直接改值 <a class="header-anchor" href="#_8-5-广播-vs-直接改值" aria-label="Permalink to “8.5 广播 vs 直接改值”">​</a></h3><ul><li>广播：传递事件意图，强调解耦</li><li>直接改值：更直接，但容易耦合过深</li></ul><hr><h2 id="_9-后续维护建议" tabindex="-1">9. 后续维护建议 <a class="header-anchor" href="#_9-后续维护建议" aria-label="Permalink to “9. 后续维护建议”">​</a></h2><ol><li>每当新增高频概念文档时，把核心术语回填到本术语表</li><li>如果不同文档对同一概念描述冲突，以官方教程与引擎更新为优先依据</li><li>若术语存在争议，应在术语项下标注“待验证”而不是直接写死</li></ol><hr><h2 id="_10-关联阅读" tabindex="-1">10. 关联阅读 <a class="header-anchor" href="#_10-关联阅读" aria-label="Permalink to “10. 关联阅读”">​</a></h2><ul><li><code>docs/元信息/知识条目统一元数据规范.md</code></li><li><code>docs/教程资料/专题研究/创游世界对象_素材_组件_脚本关系总图.md</code></li><li><code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code></li><li><code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code></li><li><code>docs/OCR资料/OCR 资料总览与完整化现状.md</code></li></ul>',109)])])}const b=l(h,[["render",d]]);export{p as __pageData,b as default};
